/* From Uiverse.io by SlowLess0 - Tags: radio */
.__UIV_SCOPE__ .rad-label {
  display: flex;
  padding: 14px 16px;
  margin: 10px 0;
  border-radius: 100px;
  cursor: pointer;
  transition: 0.3s;
}

.__UIV_SCOPE__ .rad-label:hover, .__UIV_SCOPE__ .rad-label:focus-within {
  background: hsla(0, 0%, 40%, .14);
}

.__UIV_SCOPE__ .rad-input {
  position: absolute;
  left: 0;
  top: 0;
  width: 1px;
  height: 1px;
  opacity: 0;
  z-index: -1;
}

.__UIV_SCOPE__ .rad-design {
  width: 22px;
  height: 22px;
  border-radius: 100px;
  background: linear-gradient(to right bottom, hsl(172, 97%, 62%), hsl(251, 97%, 62%));
  position: relative;
}

.__UIV_SCOPE__ .rad-design::before {
  content: '';
  display: inline-block;
  width: inherit;
  height: inherit;
  border-radius: inherit;
  background: hsl(0, 0%, 80%);
  transform: scale(1.1);
  transition: .3s;
}

.__UIV_SCOPE__ .rad-input:checked+.rad-design::before {
  transform: scale(0);
}

.__UIV_SCOPE__ .rad-text {
  color: hsl(0, 0%, 60%);
  margin-left: 14px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-size: 18px;
  font-weight: 900;
  transition: .3s;
}

.__UIV_SCOPE__ .rad-input:checked~.rad-text {
  color: hsl(0, 0%, 40%);
}
